<script setup lang="ts">
const supabase=useSupabaseClient(); const stats=reactive({switches:0,ports:0,points:0,vlans:0,faults:0}); const loading=ref(true)
onMounted(async()=>{for(const [k,t] of Object.entries({switches:'switches',ports:'switch_ports',points:'data_points',vlans:'vlans'})){const {count}=await supabase.from(t).select('*',{count:'exact',head:true});(stats as any)[k]=count||0} const {count}=await supabase.from('testing_faults').select('*',{count:'exact',head:true}).eq('outstanding',true);stats.faults=count||0;loading.value=false})
</script><template><section><div class="pagehead"><div><h2>Network Dashboard</h2><p>Live overview from Supabase.</p></div></div><div class="cards"><NuxtLink class="card" to="/switches"><b>{{loading?'—':stats.switches}}</b><span>Switches</span></NuxtLink><div class="card"><b>{{loading?'—':stats.ports}}</b><span>Mapped Ports</span></div><NuxtLink class="card" to="/data-points"><b>{{loading?'—':stats.points}}</b><span>Data Points</span></NuxtLink><NuxtLink class="card" to="/vlans"><b>{{loading?'—':stats.vlans}}</b><span>VLANs</span></NuxtLink><NuxtLink class="card warn" to="/testing"><b>{{loading?'—':stats.faults}}</b><span>Outstanding Faults</span></NuxtLink></div><div class="panel"><h3>Quick actions</h3><div class="actions"><NuxtLink class="btn" to="/switches">Manage switches</NuxtLink><NuxtLink class="btn secondary" to="/data-points">Map data points</NuxtLink><NuxtLink class="btn secondary" to="/testing">Record a test / fault</NuxtLink></div></div></section></template>
